"""Contribuicao sobre emissao/correcao, sensibilidade completa e origem declarada."""
from copy import deepcopy
from .writing import pt,pct,pp,table
from .writing_v3 import renumber

def effect_interpretation(effect):
    lo,hi=effect['ci95']
    if lo>0:return 'O IC95% permanece acima de zero neste orçamento.'
    if hi<0:return 'O IC95% está abaixo de zero neste orçamento.'
    return 'O IC95% inclui zero: este recorte não estabelece vantagem conclusiva a 4.096 tokens, nem demonstra equivalência.'

def manuscript(base,original,high,mesh,telemetry):
    d=deepcopy(base);d['draft_notice']='RASCUNHO V5 PARA REVISÃO AUTORAL — NÃO SUBMETIDO'
    old={r['condition']:r for r in original['conditions']};new={r['condition']:r for r in high['conditions']}
    a=original['paired_Ceq_minus_Beq'];b=high['paired_Ceq_minus_Beq'];errs={(r['condition'],r['type']):r['count'] for r in high['errors']}
    numeric_errors=sum(r['value_outside_frozen_tolerance'] for r in telemetry['nontechnical_discrepancies'])
    d['abstract_pt']=(f'Avaliamos consultas ambientais em português sobre MapBiomas Coleção 11, no RN, em 2015/2025, com malha IBGE 2025 informada pelo autor. Foram declaradas revisões humanas de 120 perguntas e 88 gabaritos, sem correções. O experimento original avalia o fluxo ponta a ponta sob contratos distintos. Um controle exploratório fornece planos corretos às mesmas 88 consultas, com contrato final igual. A 2.048 tokens, B_eq/C_eq acertaram {old["B_eq"]["correct"]}/88 e {old["C_eq"]["correct"]}/88; diferença {pp(a["difference_C_minus_B"])} pp, IC95% [{pp(a["ci95"][0])}; {pp(a["ci95"][1])}]. Uma sensibilidade adicional manteve prompts, planos e critérios a 4.096 tokens: {new["B_eq"]["correct"]}/88 e {new["C_eq"]["correct"]}/88; diferença {pp(b["difference_C_minus_B"])} pp, IC95% [{pp(b["ci95"][0])}; {pp(b["ci95"][1])}]. Disponibilizar cálculo aumentou respostas válidas e corretas sob o orçamento inicial; não demonstra maior capacidade aritmética do LLM. Resultados com plano fornecido não medem interpretação de perguntas inéditas ou verdade de campo.')
    d['abstract_en']=(f'We evaluate Portuguese environmental queries over MapBiomas Collection 11 in Rio Grande do Norte, Brazil, for 2015/2025, using an IBGE 2025 mesh reported by the author. Human reviews of 120 questions and 88 references were declared without corrections. The original experiment evaluates the full pipeline under different contracts. An exploratory control supplies correct plans for 88 reused queries with identical final contracts. At 2,048 tokens, B_eq/C_eq achieved {old["B_eq"]["correct"]}/88 and {old["C_eq"]["correct"]}/88; difference {100*a["difference_C_minus_B"]:.2f} pp, 95% CI [{100*a["ci95"][0]:.2f}; {100*a["ci95"][1]:.2f}]. An additional sensitivity analysis retained prompts, plans and criteria at 4,096 tokens: {new["B_eq"]["correct"]}/88 and {new["C_eq"]["correct"]}/88; difference {100*b["difference_C_minus_B"]:.2f} pp, 95% CI [{100*b["ci95"][0]:.2f}; {100*b["ci95"][1]:.2f}]. Providing computed results increased valid and correct responses under the initial budget, without demonstrating improved intrinsic arithmetic. Supplied-plan results do not measure interpretation of unseen questions or field truth.')
    blocks=[]
    for block in d['blocks']:
        q=deepcopy(block);text=q.get('text','')
        if text.startswith('O snapshot fixo das tabelas internas'):
            q['text']='Os limites de municípios e UF são do IBGE, edição 2025 informada pelo autor [11]. O snapshot fixo foi extraído das tabelas sbsr.municipios/sbsr.uf em 19/10/2026: 167 municípios do RN e uma UF, EPSG:4326, sem reparos. O arquivo importado, histórico de transformação, data original e licença específica não foram autenticados; a aquisição direta dos ZIPs oficiais encontrou timeout. GeoJSON das geometrias utilizadas, hashes por território, validade e aquisição ficam no suplemento. O IBGE descreve SIRGAS 2000; o SRID do snapshot não comprova transformação de datum.'
        elif text.startswith('O controle foi congelado antes das novas chamadas'):
            q['text']='O controle inicial foi congelado antes das chamadas e precedido por oito casos de desenvolvimento por condição. Uma sensibilidade adicional repetiu os 88 pares completos a 4.096 tokens: mesmos prompts, tabelas, planos, esquema, critérios, modelo, temperatura, timeout, reparo, ordem e concorrência; somente o teto de geração muda. O protocolo novo foi congelado antes da execução, após o diagnóstico V4, sem substituir resultados iniciais. Quatro casos por condição foram repetidos separadamente em cada orçamento.'
            blocks.append(q);blocks.append({'kind':'paragraph','text':'O IC95% usa bootstrap pareado por oito famílias, 10.000 réplicas e a mesma seed 20271021 nos dois controles [10]. Casos reutilizados e dependência territorial limitam a inferência; o IC é de acerto, não de hectares. Como os orçamentos foram executados em momentos distintos, suas diferenças também podem refletir variação remota não observável.'});continue
        elif q['kind']=='figure' and q['file']=='fig15_controle_v4.png':
            q.update(file='fig16_sensibilidade_v5.png',caption='Figura 2. Controle com plano fornecido em dois orçamentos: 88 pares por orçamento, oito famílias; falhas incluídas. A sensibilidade não substitui o controle inicial nem mede perguntas inéditas.')
        elif text.startswith('B_eq acertou'):
            q['text']=(f'A 2.048 tokens, B_eq/C_eq acertaram {old["B_eq"]["correct"]}/88 e {old["C_eq"]["correct"]}/88; C_eq−B_eq = {pp(a["difference_C_minus_B"])} pp, IC95% [{pp(a["ci95"][0])}; {pp(a["ci95"][1])}]. B_eq teve 26 retornos vazios e uma falha de contrato; C_eq não teve falhas técnicas. Entre emitidas, a precisão foi integral em ambas. Disponibilizar resultados calculados pelo executor aumentou a taxa de respostas válidas e corretas sob esse orçamento, reduzindo falhas de emissão/conformidade; não evidencia melhora da capacidade aritmética do LLM.')
            blocks.append(q);blocks.append({'kind':'heading','text':'3.3 Sensibilidade completa: 4.096 tokens'})
            blocks.append({'kind':'paragraph','text':f'A 4.096 tokens, B_eq/C_eq acertaram {new["B_eq"]["correct"]}/88 e {new["C_eq"]["correct"]}/88: diferença {pp(b["difference_C_minus_B"])} pp, IC95% [{pp(b["ci95"][0])}; {pp(b["ci95"][1])}]. '+effect_interpretation(b)})
            blocks.append({'kind':'paragraph','text':f'B_eq teve {errs.get(("B_eq","texto_final_ausente"),0)} retornos vazios e {numeric_errors} discrepância numérica entre emitidas; C_eq teve {new["C_eq"]["technical_errors"]} falhas técnicas. Precisão entre emitidas: {pct(new["B_eq"]["precision_emitted"])} e {pct(new["C_eq"]["precision_emitted"])}. Finish_reason, HTTP, tokens, discrepâncias e latência acompanham cada caso. Nenhuma resposta nova substituiu erros antigos; não se selecionou a melhor execução.'})
            continue
        elif text=='3.3 Diagnóstico dos retornos sem texto':q['text']='3.4 Diagnóstico e interpretação'
        elif text.startswith('Os 26 casos se concentram'):
            q['text']='O diagnóstico V4, selecionado pelas 26 falhas antigas, observou 23/26 vazios a 2.048 tokens e 6/26 a 4.096, com finish_reason=length e consumo do teto nos vazios novos. Os logs antigos não preservaram esses metadados, impedindo atribuição retrospectiva de causas individuais. Esse diagnóstico selecionado é distinto da sensibilidade completa de 88 pares apresentada aqui.'
        elif text.startswith(('Um diagnóstico separado','Os contadores de entrada foram','Disponibilidade de dados no contexto')):continue
        elif q['kind']=='table' and q.get('caption','').startswith('Tabela 3.'):continue
        elif text.startswith('O contraste original avalia o sistema ponta a ponta'):
            q['text']='A contribuição é avaliar uma arquitetura que disponibiliza cálculos verificáveis ao finalizador. Sob 2.048 tokens, isso aumentou respostas válidas e corretas e reduziu falhas de emissão/conformidade; não aumentou a precisão entre respostas emitidas, já integral. '+effect_interpretation(b)+' O controle fornece plano correto e reutiliza casos; não mede interpretação inédita ou habilidade aritmética intrínseca. O experimento original continua uma comparação ponta a ponta sob contratos diferentes.'
        elif text.startswith('Há dependência entre territórios/classes'):
            q['text']='Persistem dependência entre territórios/classes, benchmark por molduras, uma UF, dois anos, um modelo e variação remota não observável. A edição IBGE 2025 é informada pelo autor; arquivo importado, licença específica e histórico de datum ainda precisam autenticação. O snapshot com hashes permite repetir recortes, sem validar acurácia temática/posicional ou verdade de campo. Mudança marginal de classificação não comprova perda bruta, causa ou inundação. São necessários casos inéditos, revisão independente e outros modelos/recortes.'
        blocks.append(q)
    blocks.append({'kind':'reference','text':'[11] IBGE. Malha Municipal: edição 2025, arquivos do Rio Grande do Norte. Portal de Geociências. Disponível em https://geoftp.ibge.gov.br/organizacao_do_territorio/malhas_territoriais/malhas_municipais/municipio_2025/UFs/RN/. Acesso em 21 out. 2026.'})
    d['blocks']=blocks;renumber(d,[]);d['word_counts']={'resumo':len(d['abstract_pt'].split()),'abstract':len(d['abstract_en'].split())};return d

def report(old,new,dev,mesh,telemetry):
    a=old['paired_Ceq_minus_Beq'];b=new['paired_Ceq_minus_Beq']
    rows=[{'budget':n,**r} for n,m in [(2048,old),(4096,new)] for r in m['conditions']]
    return '\n\n'.join(['# Revisão V5 — sensibilidade completa e proveniência territorial',
        'V1/V2/V3/V4, produção, prompts e resultados originais foram preservados. Sem submissão, publicação ou deploy.',
        '## Experimento completo a 4.096 tokens',
        'A sensibilidade repete todos os 88 pares, não somente falhas, com prompts, planos, fatos, critérios, esquema, modelo, temperatura, timeout, política de reparo, ordem e concorrência iguais. O teto de saída é 4.096 nas duas condições. O wrapper registra metadados sem alterar mensagens. O protocolo novo foi congelado antes das chamadas, depois de observar o diagnóstico V4; não é pré-registro anterior ao experimento original nem teste externo novo.',
        table(['Teto','Condição','Acerto','Taxa','Emitidas','Precisão emitida','Falhas técnicas'],[
            [r['budget'],r['condition'],f'{r["correct"]}/{r["cases"]}',pct(r['accuracy']),r['answered'],pct(r['precision_emitted']),r['technical_errors']] for r in rows]),
        f'A 2.048: diferença {pp(a["difference_C_minus_B"])} pp, IC95% [{pp(a["ci95"][0])}; {pp(a["ci95"][1])}]. A 4.096: {pp(b["difference_C_minus_B"])} pp, IC95% [{pp(b["ci95"][0])}; {pp(b["ci95"][1])}]. '+effect_interpretation(b),
        'Não se infere equivalência de um IC que inclui zero. O efeito medido é taxa de respostas válidas/corretas sob plano fornecido e orçamento, incluindo falhas técnicas. Não se atribui aumento de capacidade cognitiva ou aritmética. A mudança entre orçamentos pode incluir variação temporal da infraestrutura/modelo remoto; não é um experimento fatorial simultâneo.',
        f'Desenvolvimento: {dev["primary_records"]} registros reais, antes do teste. Sensibilidade: {new["primary_records"]} registros principais e {new["repeat_records"]} repetições separadas. Repetições iguais ao inicial: {sum(r["same_answer"] for r in new["repeatability"])}/{len(new["repeatability"])}. Temperatura zero não garante determinismo. Custos permanecem null; não se escolheu a melhor resposta.',
        table(['Condição','Diagnóstico','Casos'],[[r['condition'],r['type'],r['count']] for r in new['errors']]),
        '## Telemetria do novo controle',json_code(telemetry),
        'Os contadores em http_events incluem respostas sem texto, que o cliente original descartava antes de retornar ChatResult. Não se preenchem logs antigos retroativamente. Uso capturado no transporte e uso de tentativas aceitas são apresentados separadamente, sem estimar tokens ausentes ou preço. Campos de raciocínio só têm presença/contadores; nenhum texto de raciocínio, corpo HTTP, Authorization ou token OAuth2 foi persistido.',
        '## Malha territorial: origem informada e reprodução',
        'O usuário/autor confirmou IBGE e edição 2025 para municípios e UF. O informe está registrado com data e escopo; não é tratado como comprovante do ZIP importado ou histórico de transformação. A cobertura de uso do solo é do MapBiomas; a verificação dos intervalos usados do espelho permanece a mesma da V2.',
        f'Snapshot original: {mesh["snapshot_file_sha256"]}; hash lógico: {mesh["mesh_logical_sha256"]}. O GeoJSON limites_RN_utilizados.geojson contém exatamente as geometrias utilizadas, sem reparos/reprojeção. Hash: {mesh["derived_geojson_sha256"]}. Inventário por código inclui hashes de geometria/EWKB, tipo, número de coordenadas, bbox, SRID, validade e diagnóstico de reparo.',
        'Comparação com ZIPs oficiais: '+mesh['comparison_state']+'. Estados de aquisição: '+str([{k:f.get(k) for k in ['url','state','http_status','reason']} for f in mesh['official_files']])+'. Timeout não significa arquivo ausente, geometria divergente ou edição incorreta.',
        'O portal oficial identifica os arquivos [RN_Municipios_2025.zip e RN_UF_2025.zip]('+ 'https://geoftp.ibge.gov.br/organizacao_do_territorio/malhas_territoriais/malhas_municipais/municipio_2025/UFs/RN/' +'). A documentação [Malha Municipal do IBGE](https://www.ibge.gov.br/geociencias/organizacao-do-territorio/malhas-territoriais/15774-mlhas.html) descreve coordenadas geográficas SIRGAS 2000. O snapshot foi extraído com SRID 4326; o histórico de transformação/atribuição de datum não foi fornecido. Não se alterou o CRS nem se reprocessaram áreas para apagar essa limitação.',
        'Data de edição 2025 não é data de publicação ou importação. Last-Modified HTTP não foi tratado como data de publicação. A licença específica do arquivo histórico continua sem autenticação; a origem IBGE não dispensa atribuição e confirmação dos termos antes de redistribuir. Publicação do GeoJSON continua condicional. O metadado territorial_edition=null do snapshot histórico é preservado; o sidecar atual registra a declaração posterior.',
        '## Coerência e reprodução',
        'Os 88 gabaritos e 104 valores foram revisados conforme declaração humana já registrada na V4, com recálculo independente. Os novos casos mantêm os hashes do mesmo conjunto, suportes comuns, legenda, malha e execução geoespacial. Não houve ajuste ao sistema usando resultados de teste. O experimento original avalia interpretação+execução; controles fornecem planos corretos. Taxas entre tarefas não decompõem uma contribuição causal isolada do executor.',
        'Normas e bibliografia anteriores foram preservadas; acrescentou-se fonte primária IBGE. Autoria e afiliações ainda precisam revisão. O pacote numérico da aplicação e o ambiente de execução original não foram alterados.'])+'\n'

def json_code(value):
    import json
    return '```json\n'+json.dumps(value,ensure_ascii=False,indent=2)+'\n```'
